# =============================================================================
# EmpatIA - dashboard publico
# =============================================================================
#
# El dashboard de marca contesta "como le fue a esta marca". Este contesta otra
# pregunta: "como esta el mercado". No se elige una marca; se eligen un publico y
# una edicion, y todo lo que se muestra describe al conjunto.
#
# Por eso aqui no hay anonimizacion que administrar: son los rankings publicados,
# la importancia declarada de los atributos y la estructura de posicionamiento,
# todo material que ya sale en el informe.
#
# Tres secciones:
#
#   Ranking        quien lidera, por publico y edicion tras edicion
#   Importancia    que esperan las personas, por publico y edicion tras edicion
#   Territorios    como se agrupan las marcas por la forma de su perfil
#
# La presentacion es la misma del dashboard de marca: mismos colores, misma
# tarjeta de resultado -titulo, figura, conclusion y desplegable "Métodos"- y
# misma barra lateral. Quien pasa de un tablero al otro no deberia notar que
# cambio de aplicacion.
#
# Para abrirlo: abrir este archivo y apretar "Run App" en RStudio.


library(shiny)
library(bslib)
library(bsicons)

# Se nombran los paquetes uno por uno en vez de cargar tidyverse entero. El
# tablero se sirve como sitio estatico, donde cada paquete es una descarga que
# el visitante espera antes de ver la primera pantalla, y tidyverse arrastra
# ademas googledrive, googlesheets4, haven, httr, rvest y la cadena de
# rmarkdown, que aqui no se usan. Esta es la lista completa de lo que el
# archivo llama: al agregar una funcion nueva, revisar que su paquete este.
library(dplyr)
library(tidyr)     # pivot_wider, unnest
library(purrr)     # map y familia, imap, list_rbind, set_names
library(stringr)   # str_c, str_count, str_replace_all, str_wrap
library(tibble)    # tibble
library(ggplot2)

library(plotly)
library(reactable)


# ==============================================================================
# 1. Encontrar los datos y cargar las ediciones disponibles
# ==============================================================================
# La aplicacion se abre de dos maneras, igual que el dashboard de marca:
#
#   en el proyecto  desde la carpeta dashboard_publico de un anio, con el
#                   proyecto completo alrededor. Lee los datos recien
#                   calculados.
#   publicada       en un servidor, donde solo existe esta carpeta. Los datos
#                   viajan en publicacion/, que arma
#                   compartido/preparar_publicacion.R.

buscar_proyecto <- function() {
  candidatos <- unique(c(getwd(), dirname(getwd()), dirname(dirname(getwd()))))
  con_proyecto <- candidatos[dir.exists(file.path(candidatos, "compartido"))]
  if (length(con_proyecto) == 0) return(NULL)
  normalizePath(con_proyecto[1])
}

proyecto <- buscar_proyecto()
carpeta_publicacion <- "publicacion"

if (is.null(proyecto) && !dir.exists(carpeta_publicacion)) {
  stop("No se encontraron los datos. Abrir la aplicacion desde el proyecto, o ",
       "publicarla junto a la carpeta publicacion/ (ver compartido/preparar_publicacion.R).",
       call. = FALSE)
}

archivo_edicion <- function(anio_archivo) {
  if (is.null(proyecto)) {
    file.path(carpeta_publicacion, paste0("datos_dashboard_", anio_archivo, ".rds"))
  } else {
    file.path(proyecto, anio_archivo, "dashboard", "datos_dashboard.rds")
  }
}

# Rango candidato: abajo se filtra por las ediciones que existen, asi que sobrar
# anios no cuesta nada y fijar el ultimo deja fuera la edicion siguiente.
ediciones <- as.character(2023:2035)

ediciones_disponibles <- ediciones[file.exists(map_chr(ediciones, archivo_edicion))]

datos_por_edicion <- ediciones_disponibles %>%
  set_names() %>%
  map(\(anio_archivo) readRDS(archivo_edicion(anio_archivo)))

edicion_final <- tail(ediciones_disponibles, 1)

# Bloques de atributos que se pueden seguir en el tiempo: los que aparecen en mas
# de una edicion. "IA responsable" nace en 2026, asi que todavia no entra a la
# vista de tendencia -una sola medicion no sube ni baja-, pero si a las vistas
# de la edicion actual.
orden_dimensiones <- c("Humanidad", "Tecnologia", "EmpatIA", "IA responsable")

# Se lee de importancia_segmentos y no de importancia: al publicar el sitio la
# edicion viaja recortada a las cuatro piezas que este tablero usa, y esa es la
# que llega. Ver piezas_dashboard_publico en compartido/preparar_publicacion.R.
dimensiones_por_edicion <- datos_por_edicion %>%
  map(\(d) unique(discard(as.character(d$importancia_segmentos$dimension), is.na)))

dimensiones_comparables <- dimensiones_por_edicion %>%
  unlist() %>%
  table() %>%
  keep(\(n) n >= 2) %>%
  names()

dimensiones_comparables <- c(
  intersect(orden_dimensiones, dimensiones_comparables),
  setdiff(dimensiones_comparables, orden_dimensiones)
)

# Para los menus: "Tecnologia" se muestra con tilde y viaja sin ella.
con_tilde <- function(bloques) {
  set_names(bloques, str_replace(bloques, "^Tecnologia$", "Tecnología"))
}

# Base minima para que una marca aparezca ordenada en un ranking de publico. Con
# menos, el puntaje depende demasiado de quienes respondieron.
base_minima_publico <- 40


# ==============================================================================
# 2. Las tablas que alimentan cada seccion
# ==============================================================================
# Se arman una vez al abrir, apilando las ediciones. El tablero despues solo
# filtra: ninguna figura recalcula nada.

apilar <- function(extraer) {
  imap(datos_por_edicion, function(edicion, anio) {
    tabla <- extraer(edicion)
    if (is.null(tabla) || nrow(tabla) == 0) return(NULL)
    tabla %>% mutate(anio = as.integer(anio))
  }) %>%
    list_rbind()
}

rankings <- apilar(\(edicion) edicion$ranking_segmentos)

importancias <- apilar(\(edicion) edicion$importancia_segmentos)

# Los territorios no se apilan: es el mismo sistema que el dashboard de marca
# -territorios_consenso, ver la seccion "Territorios" mas abajo-, y ese se lee
# edicion por edicion directamente desde datos_por_edicion, igual que alla.

publicos <- rankings %>%
  distinct(segmento, nivel) %>%
  arrange(segmento != "Total", segmento, nivel)

# Las segmentaciones viajan sin tilde en las tablas. En pantalla se muestran con
# ella; el valor que usan los filtros sigue siendo el de la tabla.
etiqueta_segmento <- c(Total = "Total", Genero = "Género", Generacion = "Generación",
                       GSE = "GSE")

nombre_segmento <- function(clave_segmento) unname(coalesce(etiqueta_segmento[clave_segmento], clave_segmento))

opciones_segmento <- unique(publicos$segmento) %>% set_names(nombre_segmento)

# Pestanas en que los resultados se abren por publico. En las demas el selector
# se desactiva.
pestanas_por_publico <- c("ranking", "importancia")


# ==============================================================================
# 3. Identidad visual
# ==============================================================================
# La misma del dashboard de marca. Los roles de color vienen de paleta.R, el
# archivo del informe, y aqui se reemplazan por la version luminosa de esos
# mismos roles. Se carga con local = TRUE para que las escalas definidas ahi
# tomen los colores redefinidos aqui abajo y no los del informe.

source("paleta.R", local = TRUE)

color_marca <- "#5B2EFF"
color_resto <- "#D5DBE4"

color_sobre  <- "#12B886"
color_bajo   <- "#FF4D6D"
color_neutro <- "#C3CBD6"

colores_dimension <- c(Humanidad = "#FF5C8A", Tecnologia = "#12B886", EmpatIA = "#3A7BFF",
                       `IA responsable` = "#F2C200", `Tecnología` = "#12B886")

colores_industria <- c(
  `Servicios financieros` = "#3A7BFF",
  Retail                  = "#FF8A3D",
  `Servicios esenciales`  = "#14C3B3",
  Aseguradoras            = "#B45CFF"
)

# Territorios: hasta ocho grupos, en tonos vivos y bien separados.
colores_grupo <- c("#5B2EFF", "#FF5C8A", "#14C3B3", "#FFA62B", "#3A7BFF",
                   "#B45CFF", "#7BC043", "#FF6B3D")

tema_empatia <- bs_theme(
  version = 5,
  bg = "#FFFFFF",
  fg = "#1D1846",
  primary = color_marca,
  secondary = "#FF8A3D",
  success = color_sobre,
  danger = color_bajo,
  base_font = font_collection(font_google("Inter", local = FALSE, wght = c(400, 500, 600, 700, 800)), "system-ui", "sans-serif"),
  "card-border-radius" = "18px"
)

theme_set(
  theme_empatia() +
    theme(panel.background = element_rect(fill = "#FAF9FF", colour = NA),
          panel.border = element_rect(fill = NA, colour = "#E6E2F5", linewidth = 0.5))
)

# --- Alto de las figuras -----------------------------------------------------
# Una figura con una fila por marca o por atributo tiene que crecer con la
# cantidad de filas: 70 marcas en un grafico de 520 pixeles dejan los nombres
# montados unos sobre otros. El alto se calcula aqui, a partir de las etiquetas
# del eje vertical, para que ninguna figura tenga que acordarse de hacerlo.
#
# El alto que se fija en la interfaz queda como minimo: una figura con pocas
# filas no se achica.

alto_por_linea <- 13   # pixeles por linea de texto de una etiqueta del eje
aire_por_fila  <- 7    # separacion entre etiquetas vecinas
alto_marco     <- 150  # eje horizontal, su titulo y la leyenda

alto_necesario <- function(figura) {

  construida <- ggplot_build(figura)
  paneles <- construida$layout$panel_params

  # Solo los ejes verticales con categorias -marcas, atributos- crecen con los
  # datos. Uno numerico se reparte en el alto que tenga.
  if (!isTRUE(paneles[[1]]$y$is_discrete())) return(NULL)

  # Las bandas de un eje miden todas lo mismo, asi que cada una tiene que
  # alcanzar para la etiqueta de mas lineas.
  alto_panel <- map_dbl(paneles, function(panel) {
    etiquetas <- as.character(panel$y$get_labels())
    if (length(etiquetas) == 0) return(0)
    lineas <- max(str_count(etiquetas, "\n") + 1, na.rm = TRUE)
    length(etiquetas) * (lineas * alto_por_linea + aire_por_fila)
  })

  # Paneles lado a lado comparten alto; paneles uno debajo del otro se suman.
  sum(tapply(alto_panel, construida$layout$layout$ROW, max)) + alto_marco
}

# Estira el contenedor del grafico hasta el alto necesario. Se hace en el
# navegador porque ahi se conoce el alto que la interfaz le dio a la figura, que
# se respeta como minimo. Plotly conserva ese alto cuando cambia el ancho de la
# ventana.
ajustar_alto <- function(grafico, alto) {
  if (is.null(alto)) return(grafico)
  htmlwidgets::onRender(grafico, "
    function(el, x, alto) {
      if (!el.dataset.altoBase) el.dataset.altoBase = el.offsetHeight;
      var final = Math.max(alto, Number(el.dataset.altoBase));
      if (Math.abs(el.offsetHeight - final) > 1) {
        el.style.height = final + 'px';
        Plotly.relayout(el, {height: final});
      }
    }", data = alto)
}

# Todos los graficos interactivos pasan por aqui: misma tipografia, misma
# leyenda, sin la barra de herramientas y con el alto que piden sus etiquetas.
interactivo <- function(figura, alto = NULL) {

  # ggplotly avisa "No shared levels found" al convertir capas que traen un
  # subconjunto filtrado. Esta verificado que los colores salen correctos, asi
  # que se silencia SOLO ese mensaje.
  convertir <- withCallingHandlers(
    ggplotly(figura, tooltip = "text"),
    warning = function(w) {
      if (grepl("No shared levels found", conditionMessage(w))) invokeRestart("muffleWarning")
    }
  )

  convertir %>%
    ajustar_alto(alto %||% alto_necesario(figura)) %>%
    config(displayModeBar = FALSE) %>%
    layout(
      legend = list(orientation = "h", x = 0, y = -0.12, title = list(text = "")),
      font = list(family = "Inter, system-ui, -apple-system, sans-serif",
                  color = "#3F3A63", size = 12),
      hoverlabel = list(bgcolor = "#FFFFFF", bordercolor = "#DCD5FF",
                        font = list(color = "#1D1846", size = 12)),
      # automargin cede espacio hasta que las etiquetas del eje quepan enteras.
      xaxis = list(automargin = TRUE, tickfont = list(size = 11)),
      yaxis = list(automargin = TRUE, tickfont = list(size = 11)),
      uniformtext = list(minsize = 9, mode = "hide"),
      margin = list(t = 20, b = 10)
    )
}

# Un numero con un decimal, o un aviso claro cuando no hay dato.
formato <- function(numero) if_else(is.finite(numero), formatC(numero, format = "f", digits = 1), "Sin datos")

con_signo <- function(numero) paste0(if_else(numero >= 0, "+", "−"), formato(abs(numero)))

miles <- function(numero) format(numero, big.mark = ".", decimal.mark = ",")

# Parte un texto largo en varias lineas. Se prefiere a str_trunc porque un
# enunciado cortado con puntos suspensivos no siempre se distingue de otro.
en_lineas <- function(cadena, ancho = 34) str_wrap(cadena, width = ancho)

entre_comillas <- function(cadena) paste0("«", cadena, "»")

enumerar <- function(elementos) {
  elementos <- as.character(elementos)
  if (length(elementos) <= 1) return(elementos)
  paste0(paste(head(elementos, -1), collapse = ", "), " y ", tail(elementos, 1))
}

# Los argumentos de las funciones de este archivo no pueden llamarse igual que
# una columna de los datos. dplyr resuelve primero las columnas y despues el
# entorno, asi que un argumento con el nombre de una columna queda tapado por
# ella y la funcion opera sobre el dato equivocado sin avisar. auditoria/
# comprobar.R lo verifica en cada corrida.
tabla <- function(contenido) {
  reactable(
    contenido,
    searchable = TRUE, pagination = TRUE, defaultPageSize = 15,
    showPageSizeOptions = TRUE, pageSizeOptions = c(15, 30, 60),
    wrap = TRUE, striped = TRUE, highlight = TRUE,
    defaultColDef = colDef(minWidth = 110),
    theme = reactableTheme(
      color = "#1D1846", borderColor = "#F1EEFA", stripedColor = "#FAF9FF",
      highlightColor = "#F3F0FF",
      headerStyle = list(color = "#4A4570", fontWeight = 600),
      searchInputStyle = list(borderColor = "#E2DBFF", borderRadius = "10px")
    ),
    language = reactableLang(
      searchPlaceholder = "Buscar en la tabla...",
      noData = "Sin resultados para esta selección",
      pageNext = "Siguiente", pagePrevious = "Anterior",
      pageInfo = "{rowStart}-{rowEnd} de {rows} filas"
    )
  )
}


# ==============================================================================
# 4. Piezas de la interfaz
# ==============================================================================
# Cada resultado se presenta igual que en el dashboard de marca: un titulo, una
# bajada breve, la figura, una conclusion y un desplegable "Métodos" con el
# detalle tecnico. El detalle metodologico va SIEMPRE en el desplegable.

# Etiqueta que dice a que publico corresponde el resultado. La completa el
# navegador cuando cambia el publico (ver scripts, mas abajo). Con aplica = NULL
# no se dibuja: es para las figuras que muestran todos los grupos a la vez.
chip_segmento <- function(aplica) {
  if (is.null(aplica)) return(NULL)
  tags$span(class = "chip-seg", `data-aplica` = if (isTRUE(aplica)) "si" else "no",
            hidden = NA)
}

resultado <- function(titulo, ..., subtitulo = NULL, metodos = NULL, por_segmento = FALSE) {
  card(
    card_header(
      div(
        div(class = "cabecera-resultado",
            div(class = "titulo-resultado", titulo),
            chip_segmento(por_segmento)),
        if (!is.null(subtitulo)) div(class = "pregunta-resultado", subtitulo)
      )
    ),
    card_body(
      ...,
      if (!is.null(metodos)) {
        tags$details(
          class = "metodos",
          tags$summary("Métodos"),
          div(class = "metodo-cuerpo", metodos)
        )
      }
    )
  )
}

# Cuerpo del desplegable: parrafos sueltos.
texto_metodo <- function(...) tagList(lapply(list(...), function(x) if (is.character(x)) p(x) else x))

# Conclusion sustantiva debajo de una figura.
conclusion <- function(...) {
  div(class = "conclusion", bs_icon("lightbulb"), div(class = "conclusion-texto", ...))
}

nota <- function(...) div(class = "lectura", ...)

estilos <- HTML("
  body { background: #F6F5FB; color: #1D1846; }
  .bslib-sidebar-layout > .main { min-width: 0; overflow: visible; background: #F6F5FB; }
  .card, .card-body { min-width: 0; overflow: visible; }

  /* --- Barra lateral fija ------------------------------------------------- */
  /* bslib le da a la capa un alto fijo del tamano de la ventana y deja que el
     contenido la desborde. Con ese alto, la barra fija solo lo es dentro de
     la primera pantalla. Se deja crecer la capa con su contenido. */
  body.bslib-page-fill { height: auto !important; min-height: 100vh; }
  body > .html-fill-container,
  .html-fill-container > .bslib-sidebar-layout { height: auto !important; flex: 1 0 auto !important; }
  .bslib-sidebar-layout > .sidebar {
    position: sticky; top: 0; align-self: start;
    max-height: 100vh; overflow-y: auto; background: #FFFFFF;
    border-right: 1px solid #ECE8F8;
  }
  .bloque-segmento { background: #F3F0FF; border: 1px solid #E2DBFF;
                     border-radius: 14px; padding: 12px 12px 4px; margin: 4px 0 12px;
                     transition: opacity .2s ease; }
  .bloque-segmento .titulo-bloque { font-weight: 700; color: #3B1FB8; font-size: .9rem;
                                    margin-bottom: 6px; display: flex; gap: 6px;
                                    align-items: center; }
  .bloque-segmento.desactivado { opacity: .45; }
  .bloque-segmento.desactivado .selectize-input { pointer-events: none; }
  .aviso-segmento { font-size: .82rem; color: #6B6690; margin: 2px 0 8px;
                    line-height: 1.4; }
  .base-segmento { font-size: .82rem; color: #3B1FB8; margin: -4px 0 8px; font-weight: 600; }

  /* --- Tarjeta de resultado ----------------------------------------------- */
  .card { border: 1px solid #ECE8F8; border-radius: 18px;
          box-shadow: 0 1px 2px #2A1B7A0A, 0 12px 32px #2A1B7A12;
          margin-bottom: 24px; background: #FFFFFF; }
  .card-header { background: #FFFFFF; border-bottom: 1px solid #F1EEFA;
                 padding: 16px 20px 12px; border-radius: 18px 18px 0 0 !important; }
  .card-body { padding: 18px 20px 20px; }
  .cabecera-resultado { display: flex; justify-content: space-between; gap: 12px;
                        align-items: flex-start; flex-wrap: wrap; }
  .titulo-resultado { font-weight: 700; color: #1D1846; font-size: 1.08rem;
                      letter-spacing: -0.015em; line-height: 1.3; }
  .pregunta-resultado { color: #6B6690; font-size: .92rem; margin-top: 4px; line-height: 1.45; }

  .chip-seg { font-size: .76rem; font-weight: 600; border-radius: 999px;
              padding: 3px 10px; background: #EFEAFF; color: #4B1FE0;
              white-space: nowrap; }
  .chip-seg.chip-total { background: #F1F2F6; color: #6B7688; }

  /* --- Encabezado --------------------------------------------------------- */
  .contexto { background: linear-gradient(115deg, #5B2EFF 0%, #B23CFF 55%, #FF6B8B 100%);
              color: #FFFFFF; border-radius: 22px; padding: 24px 28px;
              margin-bottom: 20px; box-shadow: 0 14px 34px #5B2EFF33; }
  .contexto h2 { color: #FFFFFF; margin: 0; font-weight: 800;
                 letter-spacing: -0.025em; font-size: 1.85rem; }
  .contexto p { color: #F3EDFF; margin: 7px 0 0; font-size: .95rem; }
  .contexto .etiqueta-publico { display: inline-block; background: #FFFFFF33;
                                border-radius: 999px; padding: 2px 10px; margin-left: 6px; }

  /* --- Cifras destacadas -------------------------------------------------- */
  .bslib-value-box { border: none !important; border-radius: 18px !important;
                     color: #FFFFFF !important; box-shadow: 0 10px 26px #2A1B7A1F; }
  .bslib-value-box .value-box-title { font-weight: 600; opacity: .92; }
  .bslib-value-box .value-box-value { font-weight: 800; letter-spacing: -0.02em; }
  .bslib-value-box .pie-cifra { font-size: .82rem; opacity: .9; margin: 0; }
  .bslib-value-box .value-box-showcase svg { width: 1.9rem !important; height: 1.9rem !important; opacity: .85; }
  .vb-violeta { background: linear-gradient(135deg, #5B2EFF, #8C6BFF) !important; }
  .vb-coral   { background: linear-gradient(135deg, #FF4D6D, #FF8A5B) !important; }
  .vb-menta   { background: linear-gradient(135deg, #0FB5A0, #3DD9C1) !important; }
  .vb-ambar   { background: linear-gradient(135deg, #FF9F1C, #FFC23D) !important; }
  .vb-azul    { background: linear-gradient(135deg, #3A7BFF, #6FA4FF) !important; }

  /* --- Conclusion y notas ------------------------------------------------- */
  .conclusion { display: flex; gap: 10px; background: #FFF8EB; border-radius: 12px;
                padding: 12px 15px; margin-top: 12px; color: #4A3B12;
                line-height: 1.55; font-size: .93rem; }
  .conclusion svg { color: #FF9F1C; flex: 0 0 auto; margin-top: 3px; }
  .conclusion-texto p { margin: 0 0 6px; }
  .conclusion-texto p:last-child { margin-bottom: 0; }
  .lectura { background: #F6F3FF; border-left: 3px solid #B9A8FF;
             border-radius: 0 10px 10px 0; color: #4A4570;
             padding: 10px 14px; margin-bottom: 14px; line-height: 1.55; font-size: .9rem; }
  .definicion { margin: -6px 0 20px; }
  .definicion > summary { cursor: pointer; color: #4B1FE0; font-weight: 600; font-size: .9rem; }
  .definicion > div { margin-top: 8px; }

  /* --- Desplegable de metodos --------------------------------------------- */
  .metodos { margin-top: 16px; border-top: 1px solid #F1EEFA; padding-top: 12px; }
  .metodos > summary { cursor: pointer; display: inline-flex; align-items: center;
                       gap: 7px; font-size: .85rem; font-weight: 600;
                       color: #4B1FE0; background: #F3F0FF;
                       border: 1px solid #E2DBFF; border-radius: 999px;
                       padding: 5px 14px; list-style: none; }
  .metodos > summary::-webkit-details-marker { display: none; }
  .metodos > summary::before { content: '+'; font-weight: 700; }
  .metodos[open] > summary::before { content: '−'; }
  .metodos[open] > summary { background: #5B2EFF; color: #FFFFFF; border-color: #5B2EFF; }
  .metodo-cuerpo { margin-top: 12px; padding: 14px 18px; background: #FBFAFF;
                   border: 1px solid #EEEAFB; border-radius: 12px;
                   color: #4A4570; font-size: .9rem; line-height: 1.65; }
  .metodo-cuerpo p { margin: 0 0 9px; }
  .metodo-cuerpo p:last-child { margin-bottom: 0; }

  /* --- Controles ---------------------------------------------------------- */
  .selectize-dropdown { z-index: 3000; box-shadow: 0 10px 28px #2A1B7A22;
                        border-radius: 10px; border: 1px solid #E2DBFF; }
  .selectize-dropdown .active { background: #5B2EFF; color: #FFFFFF; }
  .selectize-input { min-height: 40px; border-radius: 10px; border-color: #E2DBFF; }
  .selectize-input.focus { border-color: #8C6BFF; box-shadow: 0 0 0 3px #8C6BFF33; }
