# El texto de las etiquetas de publico y el bloqueo del selector se resuelven en
# el navegador: son varias etiquetas y no vale la pena un output por cada una.
scripts <- HTML("
  Shiny.addCustomMessageHandler('publico', function(m) {
    document.querySelectorAll('.chip-seg').forEach(function(el) {
      if (!m.activo) { el.hidden = true; return; }
      el.hidden = false;
      if (el.dataset.aplica === 'si') {
        el.textContent = 'Público: ' + m.etiqueta;
        el.classList.remove('chip-total');
      } else {
        el.textContent = 'Muestra total · no se abre por público';
        el.classList.add('chip-total');
      }
    });
  });

  Shiny.addCustomMessageHandler('segmento_aplica', function(m) {
    var bloque = document.getElementById('bloque-segmento');
    if (!bloque) return;
    bloque.classList.toggle('desactivado', !m.aplica);
    ['segmento', 'nivel'].forEach(function(id) {
      var s = document.getElementById(id);
      if (!s) return;
      if (s.selectize) { if (m.aplica) s.selectize.enable(); else s.selectize.disable(); }
      else { s.disabled = !m.aplica; }
    });
    var aviso = document.getElementById('aviso-segmento');
    if (aviso) aviso.hidden = m.aplica;
  });
")


