server <- function(input, output, session) {

  # --- Selectores encadenados -------------------------------------------------

  observeEvent(input$segmento, {
    grupos <- publicos %>% filter(segmento == input$segmento) %>% pull(nivel)
    updateSelectInput(session, "nivel", choices = grupos, selected = grupos[1])
  })

  observeEvent(input$anio, {

    industrias <- rankings %>%
      filter(anio == as.integer(input$anio), !is.na(industria)) %>%
      distinct(industria) %>%
      arrange(industria) %>%
      pull(industria)

    walk(c("industria_ranking", "industria_tiempo"), \(control) {
      updateSelectInput(session, control,
                        choices = c("Todas", industrias), selected = "Todas")
    })

    categorias <- rankings %>%
      filter(anio == as.integer(input$anio), !is.na(categoria)) %>%
      distinct(categoria) %>%
      arrange(categoria) %>%
      pull(categoria)

    walk(c("categoria_ranking", "categoria_tiempo"), \(control) {
      updateSelectInput(session, control,
                        choices = c("Todas", categorias), selected = "Todas")
    })

    bloque <- datos_por_edicion[[input$anio]]$territorios_consenso
    if (!is.null(bloque)) {
      resumen <- bloque$territorios %>% arrange(territorio)
      updateSelectInput(session, "territorio_elegido",
                        choices = set_names(resumen$territorio, resumen$nombre),
                        selected = resumen$territorio[1])
    }
  })

  observeEvent(input$industria_ranking, {
    categorias_de_industria <- rankings %>%
      filter(anio == as.integer(input$anio), !is.na(categoria))
    if (input$industria_ranking != "Todas") {
      categorias_de_industria <- categorias_de_industria %>%
        filter(industria == input$industria_ranking)
    }
    categorias_de_industria <- categorias_de_industria %>%
      distinct(categoria) %>% arrange(categoria) %>% pull(categoria)
    updateSelectInput(session, "categoria_ranking",
                      choices = c("Todas", categorias_de_industria), selected = "Todas")
  }, ignoreInit = TRUE)

  observeEvent(input$industria_tiempo, {
    categorias_de_industria <- rankings %>%
      filter(anio == as.integer(input$anio), !is.na(categoria))
    if (input$industria_tiempo != "Todas") {
      categorias_de_industria <- categorias_de_industria %>%
        filter(industria == input$industria_tiempo)
    }
    categorias_de_industria <- categorias_de_industria %>%
      distinct(categoria) %>% arrange(categoria) %>% pull(categoria)
    updateSelectInput(session, "categoria_tiempo",
                      choices = c("Todas", categorias_de_industria), selected = "Todas")
  }, ignoreInit = TRUE)

  observeEvent(list(input$anio, input$segmento), {
    grupos <- publicos %>% filter(segmento == input$segmento) %>% pull(nivel)
    updateSelectInput(session, "grupo_a", choices = grupos, selected = grupos[1])
    updateSelectInput(session, "grupo_b", choices = grupos,
                      selected = grupos[min(2, length(grupos))])
  })

  # --- El publico y la edicion vigentes ---------------------------------------

  publico <- reactive({
    elegido <- input$nivel %||% "Total"
    activo <- !identical(input$segmento %||% "Total", "Total")
    list(activo = activo,
         etiqueta = if (activo) elegido else "Total",
         # Para usar dentro de una frase: "entre las mujeres", "en el total".
         en_frase = if (activo) paste0("en el grupo ", elegido) else "en la muestra total")
  })

  observe({
    session$sendCustomMessage("publico", list(activo = publico()$activo,
                                              etiqueta = publico()$etiqueta))
  })

  observe({
    aplica <- is.null(input$pestana) || input$pestana %in% pestanas_por_publico
    session$sendCustomMessage("segmento_aplica", list(aplica = aplica))
  })

  personas_del_publico <- reactive({
    req(input$nivel)
    fila <- importancias %>%
      filter(anio == as.integer(input$anio),
             segmento == input$segmento, nivel == input$nivel)
    if (nrow(fila) == 0) NA_integer_ else max(fila$base)
  })

  output$base_segmento <- renderUI({
    n <- personas_del_publico()
    if (!publico()$activo || is.na(n)) return(NULL)
    div(class = "base-segmento", paste0(miles(n), " personas en el grupo"))
  })

  ranking_publico <- reactive({
    req(input$nivel)
    filas <- rankings %>%
      filter(anio == as.integer(input$anio),
             segmento == input$segmento, nivel == input$nivel,
             conocimiento >= base_minima_publico, !is.na(indice_empatia))
    validate(need(nrow(filas) > 0, "Sin marcas con base suficiente en este público."))
    filas %>% arrange(desc(indice_empatia))
  })

  output$contexto_ranking <- renderUI({
    filas <- ranking_publico()
    div(
      class = "contexto",
      h2("Mercado"),
      p(paste("Edición", input$anio, "·", nrow(filas), "marcas en el ranking EmpatIA"),
        if (publico()$activo) tags$span(class = "etiqueta-publico", publico()$etiqueta))
    )
  })

  # --- Cifras destacadas ------------------------------------------------------

  output$vb_marcas <- renderText(nrow(ranking_publico()))

  output$vb_marcas_pie <- renderText({
    paste(n_distinct(ranking_publico()$industria), "industrias")
  })

  output$vb_lider <- renderText(first(ranking_publico()$marca))

  output$vb_lider_pie <- renderText({
    lider <- ranking_publico() %>% slice(1)
    paste(na.omit(c(lider$industria, lider$categoria)), collapse = " · ")
  })

  output$vb_indice_lider <- renderText(formato(100 * first(ranking_publico()$indice_empatia)))

  output$vb_indice_lider_pie <- renderText({
    filas <- ranking_publico()
    if (nrow(filas) < 2) return("Única marca con base suficiente")
    paste(con_signo(100 * (filas$indice_empatia[1] - filas$indice_empatia[2])),
          "puntos sobre", filas$marca[2])
  })

  output$vb_personas <- renderText({
    n <- personas_del_publico()
    if (is.na(n)) "Sin datos" else miles(n)
  })

  output$vb_personas_pie <- renderText(paste("Edición", input$anio))

  # --- Ranking ----------------------------------------------------------------

  definicion_ranking <- reactive({
    configuracion <- datos_por_edicion[[input$anio]]$config
    paste0(
      "El ranking EmpatIA ordena las marcas del estudio según su Índice EmpatIA. ",
      "El índice combina dos atributos: la proporción de quienes conocen la marca ",
      "que la considera cercana (peso ", round(100 * (configuracion$peso_cercania %||% 0.5)),
      "%) y la que la considera tecnológica (", round(100 * (configuracion$peso_tecnologia %||% 0.5)),
      "%). Va de 0 a 100. Entran al ranking las marcas que conocen al menos ",
      base_minima_publico, " personas del público elegido; con menos, el puntaje es ",
      "demasiado inestable para ordenarlas."
