  # --- Territorios ------------------------------------------------------------
  # El mismo sistema que el dashboard de marca: territorios_consenso. Se
  # remuestrea a las personas cien veces, se recalculan los puntajes y en cada
  # remuestreo se agrupan las marcas con cinco algoritmos (Ward, medoides,
  # k-medias, espectral y mezcla gaussiana); la particion final es la que se
  # sostiene en ese consenso. Aqui se dibuja la version de mercado -sin una
  # marca elegida- de las mismas piezas que usa el dashboard de marca.

  bloque_territorios <- reactive({
    bloque <- datos_por_edicion[[input$anio]]$territorios_consenso
    validate(need(!is.null(bloque), "Esta edición aún no tiene calculados los territorios."))
    bloque$marcas <- bloque$marcas %>%
      left_join(bloque$territorios %>% select(territorio, nombre), by = "territorio")
    bloque$colores <- set_names(colores_grupo[seq_len(nrow(bloque$territorios))],
                                bloque$territorios$territorio)
    bloque
  })

  # Zona densa de un territorio: el contorno de densidad que encierra cerca del
  # 60% de sus marcas. Dibuja una forma organica en vez de una elipse forzada.
  # Identica a la del dashboard de marca.
  contorno_territorio <- function(coord_x, coord_y, limites, masa = 0.6) {
    if (length(coord_x) < 4) return(NULL)
    ancho <- c(MASS::bandwidth.nrd(coord_x), MASS::bandwidth.nrd(coord_y)) * 0.9
    ancho[!is.finite(ancho) | ancho <= 0] <- diff(range(c(coord_x, coord_y))) / 4
    densidad <- MASS::kde2d(coord_x, coord_y, h = ancho, n = 90, lims = limites)
    valores <- sort(as.vector(densidad$z), decreasing = TRUE)
    corte <- valores[which(cumsum(valores) / sum(valores) >= masa)[1]]
    lineas <- contourLines(densidad$x, densidad$y, densidad$z, levels = corte)
    if (length(lineas) == 0) return(NULL)
    imap_dfr(lineas, \(l, i) tibble(x = l$x, y = l$y, pieza = i))
  }

