  output$mapa_territorios <- renderPlotly({

    bloque <- bloque_territorios()

    marcas_mapa <- bloque$marcas %>%
      mutate(
        # x e y salen de plano[marca, 1:2] en territorios_consenso.R, indexado
        # por nombre: heredan el nombre de fila. Una anotacion armada con pmap
        # sobre una columna nombrada serializa cada valor como {marca: x} en vez
        # de un numero, y plotly la rechaza al construir el grafico.
        x = unname(x), y = unname(y),
        text = paste0("<b>", marca, "</b><br>", industria, " · ", categoria,
                      "<br>Territorio: ", nombre,
                      "<br>Nitidez: ", round(100 * nitidez), "%",
                      "<br>Conocen la marca: ", conocimiento)
      )

    rango_x <- range(marcas_mapa$x)
    rango_y <- range(marcas_mapa$y)
    holgura <- 0.12 * max(diff(rango_x), diff(rango_y))
    limites <- c(rango_x + c(-holgura, holgura), rango_y + c(-holgura, holgura))

    figura <- plot_ly()

    # 1. Zonas de cada territorio
    for (t in bloque$territorios$territorio) {
      miembros <- marcas_mapa %>% filter(territorio == t)
      contorno <- contorno_territorio(miembros$x, miembros$y, limites)
      if (is.null(contorno)) next
      for (pieza_actual in unique(contorno$pieza)) {
        trazo <- contorno %>% filter(pieza == pieza_actual)
        figura <- figura %>%
          add_trace(x = trazo$x, y = trazo$y, type = "scatter", mode = "lines",
                    fill = "toself", fillcolor = paste0(bloque$colores[[as.character(t)]], "22"),
                    line = list(color = paste0(bloque$colores[[as.character(t)]], "88"),
                                width = 1.5, shape = "spline"),
                    hoverinfo = "skip", showlegend = FALSE)
      }
    }

    # 2. Flechas de los atributos que mejor se leen en el plano
    flechas <- bloque$flechas %>% slice_max(largo, n = 9)
    escala <- 0.85 * max(abs(c(marcas_mapa$x, marcas_mapa$y)))
    anotaciones <- c(
      pmap(list(flechas$x, flechas$y), \(fx, fy) list(
        x = fx * escala, y = fy * escala, ax = 0, ay = 0, xref = "x", yref = "y",
        axref = "x", ayref = "y", showarrow = TRUE, arrowhead = 2, arrowsize = 1,
        arrowwidth = 1.4, arrowcolor = "rgba(91,46,255,0.35)", text = ""
      )),
      pmap(list(flechas$x, flechas$y, flechas$etiqueta), \(fx, fy, texto) list(
        x = fx * escala * 1.1, y = fy * escala * 1.1, xref = "x", yref = "y",
        showarrow = FALSE, text = texto,
        font = list(size = 11, color = "#4B1FE0"),
        bgcolor = "rgba(255,255,255,0.75)"
      ))
    )

    # 3. Las marcas, un trazo por territorio para que la leyenda los nombre
    for (t in bloque$territorios$territorio) {
      miembros <- marcas_mapa %>% filter(territorio == t)
      figura <- figura %>%
        add_trace(x = miembros$x, y = miembros$y, type = "scatter", mode = "markers",
                  name = paste0(miembros$nombre[1], " (", nrow(miembros), ")"),
                  text = miembros$text, hoverinfo = "text",
                  marker = list(color = bloque$colores[[as.character(t)]],
                                size = 7 + 16 * sqrt(miembros$conocimiento / max(marcas_mapa$conocimiento)),
                                opacity = 0.35 + 0.6 * pmin(1, miembros$nitidez / max(marcas_mapa$nitidez)),
                                line = list(color = "#FFFFFF", width = 1)))
    }

    # 4. Nombres de los territorios, sobre su centro
    centros <- marcas_mapa %>%
      summarise(x = weighted.mean(x, nitidez), y = weighted.mean(y, nitidez), .by = c(territorio, nombre))

    anotaciones <- c(
      anotaciones,
      pmap(list(centros$x, centros$y, centros$nombre, centros$territorio), \(cx, cy, texto, t) list(
        x = cx, y = cy, xref = "x", yref = "y", showarrow = FALSE,
        text = paste0("<b>", str_wrap(texto, 22) %>% str_replace_all("\n", "<br>"), "</b>"),
        font = list(size = 13, color = bloque$colores[[as.character(t)]]),
        bgcolor = "rgba(255,255,255,0.8)", borderpad = 4
      ))
    )

    # 5. La marca mas iconica de cada territorio: la de mayor nitidez y, entre
    # empatadas, la mas conocida. Es la que mejor ancla el territorio.
    iconos <- marcas_mapa %>%
      arrange(desc(nitidez), desc(conocimiento)) %>%
      distinct(territorio, .keep_all = TRUE)

    anotaciones <- c(
      anotaciones,
      pmap(list(iconos$x, iconos$y, iconos$marca, iconos$territorio), \(mx, my, texto, t) list(
        x = mx, y = my, xref = "x", yref = "y", text = paste0("<b>", texto, "</b>"),
        showarrow = TRUE, arrowhead = 0, ax = 0, ay = -22,
        arrowcolor = bloque$colores[[as.character(t)]],
        font = list(size = 11, color = bloque$colores[[as.character(t)]]),
        bgcolor = "rgba(255,255,255,0.88)", borderpad = 3
      ))
    )

    eje <- list(title = "", showgrid = FALSE, zeroline = TRUE, zerolinecolor = "#EEEAFB",
                showticklabels = FALSE, range = limites[1:2])

    figura %>%
      layout(
        xaxis = modifyList(eje, list(range = limites[1:2])),
        yaxis = modifyList(eje, list(range = limites[3:4])),
        annotations = anotaciones,
        plot_bgcolor = "#FFFFFF", paper_bgcolor = "#FFFFFF",
        legend = list(orientation = "h", x = 0, y = -0.04)
      ) %>%
      config(displayModeBar = FALSE)
  })

  output$pie_mapa_territorios <- renderUI({
    bloque <- bloque_territorios()
    mayor <- bloque$territorios %>% slice_max(marcas, n = 1, with_ties = FALSE)
    nitidez_media <- weighted.mean(bloque$marcas$nitidez, bloque$marcas$conocimiento)
    difusas <- sum(bloque$marcas$nitidez < 0.45, na.rm = TRUE)
    conclusion(
      paste0("El territorio más grande es ", entre_comillas(mayor$nombre), ", con ", mayor$marcas,
             " marcas. La nitidez promedio de la asignación es ", round(100 * nitidez_media), "%. ",
             if (difusas > 0) {
               paste0(difusas, if (difusas == 1) " marca está" else " marcas están",
                      " a medio camino entre dos territorios. ")
             } else "Todas las marcas pertenecen con claridad a su territorio. ",
             "Los territorios casi no coinciden con las industrias (índice de Rand ajustado ",
             formato(bloque$parecido_a_industria), ").")
    )
  })

  output$metodo_territorios <- renderUI({
    bloque <- bloque_territorios()
    elegido <- bloque$seleccion %>% filter(elegido)
    metodos <- bloque$metodos
    p(paste0(
      "Se elige el mayor número de territorios en que todos se sostienen: sus marcas quedan juntas en al menos el ",
      round(100 * bloque$consenso_exigido), "% de las agrupaciones y ninguno tiene menos de cinco marcas. ",
      "En esta edición son ", elegido$territorios, " (consenso mínimo ", formato(100 * elegido$consenso_minimo),
      "%). Cada algoritmo por separado entrega particiones poco estables entre remuestreos (acuerdo entre ",
      formato(min(metodos$estabilidad)), " y ", formato(max(metodos$estabilidad)),
      " en el índice de Rand ajustado, donde 1 es idéntico); por eso se reporta solo el consenso."
    ))
  })

  output$firma_territorios <- renderPlotly({

    bloque <- bloque_territorios()

    nombres <- bloque$territorios %>% arrange(territorio) %>%
      mutate(eje = str_replace_all(str_wrap(nombre, 18), "\n", "<br>"))

    # Los atributos se ordenan por el territorio que mas se los apropia: la
    # matriz queda con una diagonal que se lee de un vistazo.
    orden <- bloque$firma %>%
      slice_max(apropiacion, n = 1, by = atributo, with_ties = FALSE) %>%
      arrange(territorio, apropiacion) %>%
      pull(etiqueta)

    firma <- bloque$firma %>%
      left_join(nombres %>% select(territorio, eje), by = "territorio") %>%
      mutate(
        eje = factor(eje, levels = nombres$eje),
        etiqueta = factor(etiqueta, levels = rev(orden)),
        color = case_when(!respaldado ~ "#D9DEE7", apropiacion > 0 ~ color_sobre, .default = color_bajo),
        tamano = 6 + 34 * sqrt(abs(apropiacion) / max(abs(apropiacion))),
        text = paste0("<b>", etiqueta, "</b><br>", nombres$nombre[match(territorio, nombres$territorio)],
                      "<br>Apropiación: ", con_signo(apropiacion), " puntos",
                      if_else(respaldado, "", "<br>Dentro del margen"))
      )

    composicion <- bloque$territorios %>%
      select(territorio, industrias) %>%
      unnest(industrias) %>%
      left_join(nombres %>% select(territorio, eje), by = "territorio") %>%
      mutate(eje = factor(eje, levels = nombres$eje))

    arriba <- plot_ly()
    for (industria_actual in names(colores_industria)) {
      filas <- composicion %>% filter(industria == industria_actual)
      if (nrow(filas) == 0) next
      arriba <- arriba %>%
        add_trace(x = filas$eje, y = filas$marcas_industria, type = "bar", name = industria_actual,
                  marker = list(color = colores_industria[[industria_actual]]),
                  hovertext = paste0(industria_actual, ": ", filas$marcas_industria, " marcas"),
                  hoverinfo = "text", legendgroup = "industria")
    }
    arriba <- arriba %>% layout(barmode = "stack", yaxis = list(title = "Marcas"))

    abajo <- plot_ly(firma, x = ~eje, y = ~etiqueta, type = "scatter", mode = "markers",
                     text = ~text, hoverinfo = "text", showlegend = FALSE,
                     marker = list(size = ~tamano, color = ~color, opacity = 0.9,
                                   line = list(color = "#FFFFFF", width = 1)))

    subplot(arriba, abajo, nrows = 2, heights = c(0.16, 0.84), shareX = TRUE, titleY = TRUE,
            margin = 0.02) %>%
      config(displayModeBar = FALSE) %>%
      layout(
        font = list(family = "Inter, system-ui, -apple-system, sans-serif", color = "#3F3A63", size = 12),
        hoverlabel = list(bgcolor = "#FFFFFF", bordercolor = "#DCD5FF",
                          font = list(color = "#1D1846", size = 12)),
        legend = list(orientation = "h", x = 0, y = 1.12),
        xaxis = list(title = ""), xaxis2 = list(title = "", side = "bottom", tickfont = list(size = 11)),
        yaxis2 = list(title = "", tickfont = list(size = 11), automargin = TRUE),
        margin = list(t = 60)
      )
  })

  habitantes <- reactive({
    req(input$territorio_elegido)
    bloque <- bloque_territorios()
    filas <- bloque$marcas %>% filter(territorio == as.integer(input$territorio_elegido))
    validate(need(nrow(filas) > 0, "Ese territorio no tiene marcas en esta edición."))
    filas
  })

  output$habitantes_territorio <- renderPlotly({

    datos_figura <- habitantes() %>%
      mutate(
        text = paste0(marca, "\n", coalesce(categoria, industria),
                      "\nNitidez: ", round(nitidez, 2),
                      "\nÍndice EmpatIA: ", formato(100 * indice_empatia))
      )

    figura <- datos_figura %>%
      ggplot(aes(x = reorder(marca, nitidez), y = nitidez,
                 fill = industria, text = text)) +
      geom_col(width = 0.72) +
      coord_flip() +
      scale_fill_manual(values = colores_industria, na.value = color_resto) +
      scale_y_continuous(limits = c(0, 1), expand = expansion(mult = c(0, 0.05))) +
      labs(x = NULL, y = "Qué tan claramente pertenece al territorio", fill = NULL)

    interactivo(figura)
  })

  output$pie_habitantes <- renderUI({

    filas <- habitantes()
    mejor_indice <- filas %>% slice_max(indice_empatia, n = 1, with_ties = FALSE)
    dudosas <- filas %>% filter(nitidez < 0.45) %>% arrange(nitidez)
    nombre_territorio <- filas$nombre[1]

    conclusion(
      paste0("El territorio ", entre_comillas(nombre_territorio), " tiene ", nrow(filas),
             " marcas; la de mayor Índice EmpatIA es ", mejor_indice$marca, " (",
             formato(100 * mejor_indice$indice_empatia), "). ",
             if (nrow(dudosas) > 0) {
               paste0("A medio camino con otro territorio: ",
                      enumerar(head(dudosas$marca, 5)), ".")
             } else "Todas pertenecen con claridad a este territorio.")
    )
  })
}

